                  "text": "A South-Link autópálya fárasztó, 460 méteres csúcsán található egykori rendőrőrs ma a szigetet átszelő kerékpárosok híres pihenőhelyeként szolgál.",
                  "category": "landmark",
                  "coords": [
                        120.835706,
                        22.245203
                  ]
