      hu: ["A történelmi Alangyi-ösvény hossza körülbelül 8,4 kilométer.", "A területet 2012. január 20-án nyilvánították természetvédelmi területté.", "Ez Tajvan egyetlen olyan tengerparti szakasza, ahol nincs aszfaltozott út.", "A partot különleges, simára csiszolt fekete kavicsok borítják.", "A látogatóknak legalább 3 nappal korábban engedélyt kell kérniük a belépéshez.", "A Guanyin-orr sziklái több mint 200 méterrel magasodnak a tenger fölé."],
      ro: ["Lungimea traseului istoric Alangyi este de aproximativ 8,4 kilometri.", "Zona a fost declarată rezervație naturală la data de 20 ianuarie 2012.", "Este singura secțiune de coastă din Taiwan fără o șosea asfaltată.", "Plajele sunt compuse din pietriș negru șlefuit de acțiunea valurilor.", "Vizitatorii trebuie să solicite permise de acces cu cel puțin 3 zile înainte.", "Falezele de la Guanyin-nose ating înălțimi de peste 200 de metri."],
      en: ["The total length of the Alangyi Historic Trail is approximately 8.4 kilometers.", "The area was officially designated a nature reserve on January 20, 2012.", "It is the only coastal segment in Taiwan without a paved highway.", "The beaches are composed of uniquely smooth, rounded black pebbles.", "Visitors must apply for entry permits at least 3 days in advance.", "The cliffs at Guanyin-nose rise over 200 meters above the sea."],
